import{_ as e,o as n,c as i,a2 as t}from"./chunks/framework.DtFGJNng.js";const p=JSON.parse('{"title":"Keputusan desain","description":"","frontmatter":{},"headers":[],"relativePath":"decisions.md","filePath":"decisions.md","lastUpdated":1794463556000}'),s={name:"decisions.md"};function d(r,a,o,l,u,c){return n(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="keputusan-desain" tabindex="-1">Keputusan desain <a class="header-anchor" href="#keputusan-desain" aria-label="Permalink to &quot;Keputusan desain&quot;">​</a></h1><p>deuz dibangun dari ide-ide <a href="https://github.com/Fission-AI/OpenSpec" target="_blank" rel="noreferrer">OpenSpec</a> (versi yang dipelajari: 1.17.0). Tiap entri menjelaskan apa yang dilakukan OpenSpec, apa yang dilakukan deuz sebagai gantinya, dan alasannya. Path yang diawali <code>OpenSpec/</code> merujuk ke repository OpenSpec.</p><h2 id="d1-artifact-punya-owner-role" tabindex="-1">D1. Artifact punya owner role <a class="header-anchor" href="#d1-artifact-punya-owner-role" aria-label="Permalink to &quot;D1. Artifact punya owner role&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> satu aktor (satu orang dengan agent AI) menulis semua artifact sebuah change, dari proposal sampai tasks. Schema-nya tidak mengenal siapa menulis apa (<code>OpenSpec/schemas/spec-driven/schema.yaml</code>).</li><li><strong>deuz:</strong> setiap artifact mendeklarasikan <code>owners</code>, yaitu daftar role (<code>analyst</code>, <code>designer</code>, <code>frontend</code>, <code>backend</code>, <code>qa</code>).</li><li><strong>Alasan:</strong> di kebanyakan tim produk, pekerjaan ini terbagi ke beberapa role, dan sebagian besar pengerjaan ulang terjadi di titik serah terima: layar dibangun dari spec yang setengah jadi, atau frontend menebak bentuk API. Kepemilikan yang eksplisit membuat serah terima juga eksplisit.</li></ul><h2 id="d2-ready-dikonfirmasi-bukan-disimpulkan-dari-keberadaan-file" tabindex="-1">D2. Ready dikonfirmasi, bukan disimpulkan dari keberadaan file <a class="header-anchor" href="#d2-ready-dikonfirmasi-bukan-disimpulkan-dari-keberadaan-file" aria-label="Permalink to &quot;D2. Ready dikonfirmasi, bukan disimpulkan dari keberadaan file&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> sebuah artifact dianggap selesai jika file-nya ada (<code>OpenSpec/src/core/artifact-graph/state.ts</code>).</li><li><strong>deuz:</strong> <code>missing</code> → <code>draft</code> → <code>ready</code>; artifact menjadi ready jika setiap owner role yang aktif mengonfirmasinya (<code>/deuz:ready</code>).</li><li><strong>Alasan:</strong> jika penulis dan pemakai artifact adalah orang yang sama, &quot;file-nya ada&quot; sudah cukup. Jika pemakainya orang lain, file yang ada bisa saja masih setengah jadi; role berikutnya butuh sinyal bahwa ia boleh mulai.</li></ul><h2 id="d3-solo-dan-tim-adalah-mode-bukan-schema" tabindex="-1">D3. Solo dan tim adalah mode, bukan schema <a class="header-anchor" href="#d3-solo-dan-tim-adalah-mode-bukan-schema" aria-label="Permalink to &quot;D3. Solo dan tim adalah mode, bukan schema&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> dirancang untuk satu aktor.</li><li><strong>deuz:</strong> schema yang sama melayani keduanya. deuz mencatat role, bukan orang: pengguna solo mengonfirmasi beberapa role sekaligus (<code>--as backend,frontend</code>), sedangkan di tim tiap orang mengonfirmasi satu role.</li><li><strong>Alasan:</strong> cukup satu model yang perlu dipelajari, dan work yang dimulai secara solo bisa diserahkan ke tim tanpa konversi. deuz tidak perlu tahu siapa saja anggota tim.</li></ul><h2 id="d4-work-bukan-changes" tabindex="-1">D4. <code>work/</code>, bukan <code>changes/</code> <a class="header-anchor" href="#d4-work-bukan-changes" aria-label="Permalink to &quot;D4. `work/`, bukan `changes/`&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> pekerjaan yang sedang berjalan disimpan di <code>openspec/changes/&lt;name&gt;/</code>.</li><li><strong>deuz:</strong> <code>deuz/work/&lt;name&gt;/</code>.</li><li><strong>Alasan:</strong> kata &quot;change&quot; terbaca sebagai &quot;mengubah sesuatu yang sudah ada&quot;, sehingga membingungkan orang yang memulai fitur yang benar-benar baru. Work adalah unit apa pun dari pekerjaan yang sedang berjalan.</li></ul><h2 id="d5-skip-berlaku-per-artifact-berdasarkan-role-aktif-dan-affected-area" tabindex="-1">D5. Skip berlaku per artifact, berdasarkan role aktif dan affected area <a class="header-anchor" href="#d5-skip-berlaku-per-artifact-berdasarkan-role-aktif-dan-affected-area" aria-label="Permalink to &quot;D5. Skip berlaku per artifact, berdasarkan role aktif dan affected area&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> sebuah change bisa melewati specs secara keseluruhan dengan <code>skip_specs: true</code> di <code>.openspec.yaml</code>.</li><li><strong>deuz:</strong> artifact di-skip jika tidak punya owner yang aktif (berlaku untuk seluruh project: tim tidak punya role tersebut) atau jika work tidak menyentuh area-nya (berlaku per work: checklist &quot;Affected areas&quot; di proposal: <code>design</code>, <code>frontend</code>, <code>backend</code>, <code>api</code>). Artifact yang di-skip tetap memenuhi <code>requires</code>.</li><li><strong>Alasan:</strong> komposisi tim berbeda-beda, dan cakupan tiap work juga berbeda. Tim yang hanya backend tidak pernah melihat artifact UI; perubahan logika backend yang tidak mengubah bentuk API men-skip contract. Perubahan kecil tetap ringan tanpa perlu schema &quot;lite&quot; terpisah.</li></ul><h2 id="d6-graph-mengikuti-dependensi-nyata-antar-role" tabindex="-1">D6. Graph mengikuti dependensi nyata antar-role <a class="header-anchor" href="#d6-graph-mengikuti-dependensi-nyata-antar-role" aria-label="Permalink to &quot;D6. Graph mengikuti dependensi nyata antar-role&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> <code>proposal → specs → design → tasks</code>, dengan <code>specs</code> dan <code>design</code> sama-sama hanya bergantung pada <code>proposal</code>.</li><li><strong>deuz:</strong> <code>proposal → specs → ui-design → api-contract → tasks-backend ∥ tasks-frontend ∥ tasks-test</code>.</li><li><strong>Alasan:</strong> bentuk API mengikuti apa yang perlu ditampilkan dan dilakukan oleh layar, jadi contract datang setelah desain, dan backend maupun frontend harus menyepakatinya. Begitu contract ready, backend, frontend, dan QA bisa menulis kode secara paralel; paralelisme inilah hasil dari menyepakati contract lebih dulu.</li></ul><h2 id="d7-tidak-ada-dokumen-desain-teknis-terpisah" tabindex="-1">D7. Tidak ada dokumen desain teknis terpisah <a class="header-anchor" href="#d7-tidak-ada-dokumen-desain-teknis-terpisah" aria-label="Permalink to &quot;D7. Tidak ada dokumen desain teknis terpisah&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> <code>design.md</code> berisi keputusan teknis (konteks, tujuan, keputusan, risiko).</li><li><strong>deuz:</strong> setiap tasks artifact diawali dengan <code>## Technical decisions</code>.</li><li><strong>Alasan:</strong> di tim yang punya UI/UX designer, &quot;desain&quot; berarti layar; dua artifact yang sama-sama disebut desain menimbulkan kebingungan. Selain itu, artifact terpisah hanya layak menjadi titik serah terima jika dipakai oleh role lain, sedangkan keputusan teknis dipakai oleh role yang menulis tasks itu sendiri.</li></ul><h2 id="d8-tidak-ada-artifact-test-scenarios-terpisah" tabindex="-1">D8. Tidak ada artifact test-scenarios terpisah <a class="header-anchor" href="#d8-tidak-ada-artifact-test-scenarios-terpisah" aria-label="Permalink to &quot;D8. Tidak ada artifact test-scenarios terpisah&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> tidak ada (test adalah bagian dari tasks).</li><li><strong>deuz:</strong> coverage map milik QA (scenario → test id → suite) menjadi section pertama di <code>tasks-test</code>.</li><li><strong>Alasan:</strong> satu-satunya pemakai daftar scenario adalah task list milik QA sendiri. Scenario di spec sudah menggambarkan perilaku; coverage map menambahkan di mana masing-masing diuji.</li></ul><h2 id="d9-api-contract-berupa-markdown-dimiliki-backend-dan-frontend" tabindex="-1">D9. API contract berupa Markdown, dimiliki backend dan frontend <a class="header-anchor" href="#d9-api-contract-berupa-markdown-dimiliki-backend-dan-frontend" aria-label="Permalink to &quot;D9. API contract berupa Markdown, dimiliki backend dan frontend&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> tidak ada artifact khusus API.</li><li><strong>deuz:</strong> <code>api-contract.md</code>, berisi tabel per endpoint (request, response, error, permission), dimiliki bersama oleh backend dan frontend; backend menerjemahkannya ke definisi API project saat promote.</li><li><strong>Alasan:</strong> contract adalah kesepakatan antara dua role, jadi keduanya menjadi owner. Menulisnya langsung dalam format definisi API (misalnya file OpenAPI) mencampur kesepakatan dengan tooling backend dan kode hasil generate. Menyimpan perilaku di spec dan bentuk di contract mencegah aturan ditulis ulang di dua tempat.</li></ul><h2 id="d10-home-dan-home-hanya-berisi-apa-yang-sudah-dibangun" tabindex="-1">D10. Home, dan home hanya berisi apa yang sudah dibangun <a class="header-anchor" href="#d10-home-dan-home-hanya-berisi-apa-yang-sudah-dibangun" aria-label="Permalink to &quot;D10. Home, dan home hanya berisi apa yang sudah dibangun&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> satu tempat penyimpanan permanen, <code>openspec/specs/</code>, diperbarui saat archive.</li><li><strong>deuz:</strong> setiap schema menamai sumber kebenaran permanennya (<code>specs</code>, <code>design</code>, <code>api</code>); project memetakannya ke path atau <code>null</code>. Konten masuk ke home bersamaan dengan kode yang mengimplementasikannya: specs saat archive, file desain dan definisi API sebagai task terakhir di task list frontend dan backend.</li><li><strong>Alasan:</strong> file desain dan definisi API biasanya sudah punya home yang diperiksa oleh tool (test kesesuaian visual membandingkan aplikasi dengan desain; code generator meng-compile definisi API). Menaruh desain atau endpoint yang belum dibangun di sana akan merusak pemeriksaan tersebut. Menyimpan salinan permanen kedua di dalam deuz akan menciptakan dua sumber kebenaran yang lama-lama tidak sinkron.</li></ul><h2 id="d11-review-tetap-di-luar-deuz" tabindex="-1">D11. Review tetap di luar deuz <a class="header-anchor" href="#d11-review-tetap-di-luar-deuz" aria-label="Permalink to &quot;D11. Review tetap di luar deuz&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> review tidak dimodelkan.</li><li><strong>deuz:</strong> juga tidak dimodelkan. Owner mengonfirmasi <code>ready</code>; review terjadi di pull request atau diskusi.</li><li><strong>Alasan:</strong> memodelkan reviewer menambah state dan birokrasi yang sudah ditangani oleh code review. Satu-satunya tempat di mana kesepakatan harus dicatat, yaitu API contract, ditangani lewat co-ownership (D9).</li></ul><h2 id="d12-skill-dulu-lalu-cli-go-untuk-setiap-aturan" tabindex="-1">D12. Skill dulu, lalu CLI Go untuk setiap aturan <a class="header-anchor" href="#d12-skill-dulu-lalu-cli-go-untuk-setiap-aturan" aria-label="Permalink to &quot;D12. Skill dulu, lalu CLI Go untuk setiap aturan&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> CLI TypeScript (Node 22+) menghitung status dan instruksi; skill memanggilnya. Binary standalone ditambahkan belakangan dengan <code>bun build --compile</code> (<code>OpenSpec/scripts/binary/build.mjs</code>) agar orang tanpa Node bisa memasangnya.</li><li><strong>deuz:</strong> versi pertama hanya berupa skill. Saat uji coba, agent ternyata menerapkan aturan secara tidak konsisten, sehingga setiap langkah berbasis aturan dipindahkan ke CLI yang ditulis dengan Go: satu binary tanpa dependensi per platform, dengan schema yang di-embed lewat <code>go:embed</code>. Skill memanggil CLI dan kembali ke <code>core/RULES.md</code> jika CLI tidak ada.</li><li><strong>Alasan:</strong> hasilnya harus identik di setiap agent (Claude Code, Codex, …) dan setiap role harus bisa menjalankannya, termasuk orang yang tidak akan pernah memasang runtime bahasa pemrograman. Go menghasilkan satu binary kecil secara default dan dikelola oleh engineer backend tim. Menulis konten tetap menjadi tugas agent; hanya aturan yang dipindahkan.</li></ul><h2 id="d13-satu-schema-default-komposisi-tim-ada-di-config" tabindex="-1">D13. Satu schema default; komposisi tim ada di config <a class="header-anchor" href="#d13-satu-schema-default-komposisi-tim-ada-di-config" aria-label="Permalink to &quot;D13. Satu schema default; komposisi tim ada di config&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> schema default dinamai sesuai pendekatannya, <code>spec-driven</code>.</li><li><strong>deuz:</strong> schema bawaan bernama <code>default</code>. Tim mencantumkan role aktifnya di <code>deuz/config.yaml</code> dan boleh meng-override owner sebuah artifact (misalnya tim backend saja yang produknya adalah API: <code>api-contract: [backend, analyst]</code>). Fork dipakai untuk alur yang memang berbeda (role tambahan, artifact yang berbeda).</li><li><strong>Alasan:</strong> menamai schema berdasarkan komposisi tim (full-stack, backend-only) mengikatnya ke stack tertentu dan melipatgandakan jumlah schema. Kebanyakan tim seharusnya tidak perlu menyentuh schema sama sekali.</li></ul><h2 id="d14-file-produk-berbahasa-inggris-bahasa-artifact-bisa-dikonfigurasi" tabindex="-1">D14. File produk berbahasa Inggris, bahasa artifact bisa dikonfigurasi <a class="header-anchor" href="#d14-file-produk-berbahasa-inggris-bahasa-artifact-bisa-dikonfigurasi" aria-label="Permalink to &quot;D14. File produk berbahasa Inggris, bahasa artifact bisa dikonfigurasi&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> bahasa Inggris; konteks project ada di config.</li><li><strong>deuz:</strong> file produk yang dibaca agent atau CLI (template, instruksi, skill, <code>core/RULES.md</code>, <code>core/CLI.md</code>) berbahasa Inggris. <code>language</code> di config menentukan bahasa isi artifact. Keyword normatif dan struktural (<code>SHALL</code>, <code>WHEN</code>, <code>THEN</code>, <code>## ADDED Requirements</code>, ...) tetap berbahasa Inggris agar bisa di-parse oleh tool. Dokumentasi untuk manusia diatur oleh D22.</li><li><strong>Alasan:</strong> agent dan parser butuh satu bahasa yang stabil, sementara tiap tim tetap menulis dokumennya dalam bahasanya sendiri.</li></ul><h2 id="d15-persetujuan-bisnis-adalah-sebuah-role" tabindex="-1">D15. Persetujuan bisnis adalah sebuah role <a class="header-anchor" href="#d15-persetujuan-bisnis-adalah-sebuah-role" aria-label="Permalink to &quot;D15. Persetujuan bisnis adalah sebuah role&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> persetujuan tidak dimodelkan; siapa pun yang menulis change memutuskan apakah change itu dilanjutkan.</li><li><strong>deuz:</strong> role <code>business</code> yang opsional menjadi co-owner proposal (gate 1) dan, jika diperlukan, specs (gate 2). Stakeholder tidak menjalankan deuz: analyst mencatat hasil meeting di proposal dan mengonfirmasi <code>--as business</code>.</li><li><strong>Alasan:</strong> banyak tim butuh keputusan bisnis yang tercatat sebelum development dilanjutkan. Co-ownership sudah memodelkan kesepakatan antar-role (D9), jadi gate tidak butuh state baru, dan artifact berikutnya tetap terkunci sampai business mengonfirmasi. D11 tetap berlaku: review isi tetap di luar deuz; yang dicatat hanya keputusannya.</li></ul><h2 id="d16-owner-kondisional-dari-checklist-proposal" tabindex="-1">D16. Owner kondisional dari checklist proposal <a class="header-anchor" href="#d16-owner-kondisional-dari-checklist-proposal" aria-label="Permalink to &quot;D16. Owner kondisional dari checklist proposal&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> tidak ada owner.</li><li><strong>deuz:</strong> <code>conditional_owners: [{ role, if_area }]</code> menambahkan sebuah role ke artifact jika proposal mencentang area tersebut (<code>business</code> → proposal, <code>business-rules</code> → specs). Owner kondisional milik proposal sendiri mengikuti checklist-nya sebagaimana tertulis; artifact berikutnya mengikuti area yang sudah tercatat.</li><li><strong>Alasan:</strong> perbaikan bug tidak boleh menunggu meeting, sedangkan fitur harus. Satu schema melayani keduanya, diputuskan per work, dan project tanpa role <code>business</code> tidak terpengaruh.</li></ul><h2 id="d17-proposal-melayani-bisnis-dan-engineering" tabindex="-1">D17. Proposal melayani bisnis dan engineering <a class="header-anchor" href="#d17-proposal-melayani-bisnis-dan-engineering" aria-label="Permalink to &quot;D17. Proposal melayani bisnis dan engineering&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> proposal ditujukan untuk implementer: Why, What Changes, Capabilities, Impact (<code>OpenSpec/schemas/spec-driven/templates/proposal.md</code>).</li><li><strong>deuz:</strong> bagian bisnis lebih dulu (ringkasan, alasan, tujuan dan indikator, scope beserta prioritas, siapa yang terdampak, risiko, aturan yang butuh persetujuan, pertanyaan dan keputusan, persetujuan), lalu jembatan ke engineering (capability, affected area). Aturan bisnis hanya ditunjuk; teksnya ada di specs.</li><li><strong>Alasan:</strong> dokumen yang sama dipresentasikan ke stakeholder dan diserahkan ke tim. Menulis aturan sekali saja, di specs, mencegah ketidaksinkronan antara ringkasan dan salinan detail di dua dokumen.</li></ul><h2 id="d18-jenis-work-dan-triage-yang-tercatat" tabindex="-1">D18. Jenis work dan triage yang tercatat <a class="header-anchor" href="#d18-jenis-work-dan-triage-yang-tercatat" aria-label="Permalink to &quot;D18. Jenis work dan triage yang tercatat&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> tidak ada jenis work.</li><li><strong>deuz:</strong> <code>Type</code> (feature, enhancement, bug, tech, chore). Jika role <code>business</code> aktif, feature wajib mencentang <code>business</code>; bug atau enhancement tanpa centang itu wajib mencatat baris <code>Triage:</code>. Artifact specs di-skip jika proposal yang sudah ready tidak mencantumkan capability dan tidak ada delta.</li><li><strong>Alasan:</strong> yang menentukan gate adalah dampak bisnis, bukan label, tetapi melewati gate harus meninggalkan jejak. OpenSpec men-skip specs dengan <code>skip_specs: true</code> di <code>.openspec.yaml</code>; deuz membaca daftar capability yang memang sudah ada di proposal.</li></ul><h2 id="d19-tabel-contoh-di-scenario" tabindex="-1">D19. Tabel contoh di scenario <a class="header-anchor" href="#d19-tabel-contoh-di-scenario" aria-label="Permalink to &quot;D19. Tabel contoh di scenario&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> scenario berupa bullet WHEN/THEN.</li><li><strong>deuz:</strong> sebuah scenario boleh diikuti satu tabel contoh; tiap baris adalah satu test case, dan tabel ikut digabung bersama requirement-nya.</li><li><strong>Alasan:</strong> aturan perhitungan paling jelas, dan paling mudah dicek oleh pembaca bisnis, jika ditulis sebagai input dan hasil yang diharapkan.</li></ul><h2 id="d20-approvals-berada-di-luar-hash-proposal" tabindex="-1">D20. Approvals berada di luar hash proposal <a class="header-anchor" href="#d20-approvals-berada-di-luar-hash-proposal" aria-label="Permalink to &quot;D20. Approvals berada di luar hash proposal&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> tidak ada hash konten.</li><li><strong>deuz:</strong> section <code>&lt;!-- deuz:approvals --&gt;</code> tidak ikut dihitung dalam hash proposal; semua section lain, termasuk pertanyaan dan keputusan, ikut dihitung.</li><li><strong>Alasan:</strong> gate 2 dicatat setelah gate 1. Jika approvals ikut di-hash, baris gate 2 akan membatalkan gate 1 dan menandai semua artifact berikutnya.</li></ul><h2 id="d21-manifest-work-adalah-deuz-yaml" tabindex="-1">D21. Manifest work adalah <code>.deuz.yaml</code> <a class="header-anchor" href="#d21-manifest-work-adalah-deuz-yaml" aria-label="Permalink to &quot;D21. Manifest work adalah `.deuz.yaml`&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> <code>.openspec.yaml</code> menyimpan metadata change (schema, created, goal, affected areas, initiative link, <code>skip_specs</code>, <code>retire_capabilities</code>; <code>OpenSpec/src/core/change-metadata/schema.ts:38-61</code>), tetapi tidak menyimpan metadata navigasi; urutan artifact hanya ada di schema.</li><li><strong>deuz:</strong> <code>.deuz.yaml</code> juga memuat title, requirement, dan pola file tiap artifact (<code>format: 1</code>), yang didokumentasikan di <code>docs/manifest.md</code>. <code>deuz status --write</code> menambahkannya ke work yang lebih lama.</li><li><strong>Alasan:</strong> editor dan viewer bisa menampilkan navigasi langkah demi langkah antar-dokumen sebuah work tanpa perlu mengenal schema deuz, dan tanpa frontmatter yang akan mengubah hash konten dan mengotori dokumen yang di-render. Pola file, bukan daftar file, membuat navigasi tetap mutakhir saat ada file yang ditambahkan di antara dua kali CLI dijalankan.</li></ul><h2 id="d22-dokumentasi-untuk-manusia-berbahasa-indonesia" tabindex="-1">D22. Dokumentasi untuk manusia berbahasa Indonesia <a class="header-anchor" href="#d22-dokumentasi-untuk-manusia-berbahasa-indonesia" aria-label="Permalink to &quot;D22. Dokumentasi untuk manusia berbahasa Indonesia&quot;">​</a></h2><ul><li><strong>OpenSpec:</strong> dokumentasi berbahasa Inggris.</li><li><strong>deuz:</strong> <code>README.md</code> dan semua isi <code>docs/</code> berbahasa Indonesia. File yang dibaca agent (schema, template, instruksi, skill, <code>core/RULES.md</code>, <code>core/CLI.md</code>) tetap berbahasa Inggris. Keyword struktural (<code>SHALL</code>, <code>WHEN</code>, <code>THEN</code>, <code>## ADDED Requirements</code>, <code>### Requirement:</code>, <code>#### Scenario:</code>, <code>Type</code>, <code>Triage:</code>, <code>&lt;!-- deuz:… --&gt;</code>) tetap berbahasa Inggris di mana pun.</li><li><strong>Alasan:</strong> pembaca pertama adalah tim internal, yang lebih cepat belajar dalam bahasanya sendiri. Agent dan parser butuh satu bahasa yang stabil. Entri ini menggantikan bagian dokumentasi di D14; terjemahan untuk open source bisa menyusul.</li></ul>',46)])])}const g=e(s,[["render",d]]);export{p as __pageData,g as default};
